local function invalidate()
  if ctx and ctx.invalidate then pcall(function() ctx:invalidate() end) end
end
local function notify(s)
  msg=s
  if ctx and ctx.dialog and ctx.dialog.toast then
    pcall(function() ctx.dialog:toast(s) end)
  end
  invalidate()
end
local function safe_text(s)
  -- One value only: a bare gsub return also yields its count, which used to be
  -- saved into progress.txt as an extra field and corrupt every reader link.
  return (tostring(s or ''):gsub('[\r\n\t]',' '))
end
-- Progress is saved by title key, never by position, so a new or reordered list keeps it.
-- Rows for books not in this list are kept verbatim.
local function save()
  local rows={'#roadmap2'}
  for i=1,#books do
    local s=states[i]
    if s.status~='todo' or s.rid~='' then
      rows[#rows+1]=table.concat({books[i].key,s.status,safe_text(s.rid)},'\t')
    end
  end
  for _,r in ipairs(kept_rows) do rows[#rows+1]=r end
  local ok,result=pcall(function() return ctx.storage:write('progress.txt',table.concat(rows,'\n')..'\n') end)
  if not ok or result==false then notify('Save failed; changes may not persist.'); return false end
  return true
end
local function load()
  local ok,s=pcall(function() return ctx.storage:read('progress.txt') end)
  if not ok or type(s)~='string' then return end
  local v1=s:sub(1,10)=='#roadmap1\n' or s:sub(1,11)=='#roadmap1\r\n'
  kept_rows={}
  for line in s:gmatch('[^\r\n]+') do
    local key,status,rid=line:match('^([^\t#][^\t]*)\t([%a]+)\t?(.*)$')
    if key and v1 then
      local old=tonumber(key)
      key=old and V1_KEYS[old] or ('v1:'..key)  -- v1:N = a book from the old 33-book list
    end
    local b=key and by_key[key]
    if b and (status=='todo' or status=='reading' or status=='done') then
      states[b.id].status=status
      states[b.id].rid=rid or ''
    elseif key then
      kept_rows[#kept_rows+1]=table.concat({key,status,rid or ''},'\t')
    end
  end
end
local function norm(s)
  return (safe_text(s):lower():gsub('[^%w]+',''))
end
-- Title matching. Keep identical to tools/card_from_tree.py (classify) and preview.html.
local function words(s)
  local out={}
  for w in (safe_text(s):lower():gsub('[^%w]+',' ')):gmatch('%S+') do out[#out+1]=w end
  return out
end
-- full key, main key (no subtitle/edition note), author tail, cleaned title
local function title_forms(t)
  local s=safe_text(t):lower():gsub('^%s+',''):gsub('%s+$','')
  for _,ext in ipairs({'epub','mobi','azw3','txt','pdf','prc','fb2'}) do s=s:gsub('%.'..ext..'$','') end
  s=s:gsub('^%s*%b[]%s*','')                       -- "[Murderbot Diaries 01] "
  local tail=''
  local head,rest=s:match('^(.-)%s+%-%s+(.+)$')     -- reader falls back to "Title - Author" file names
  if head then s,tail=head,rest end
  local front,art=s:match('^(.*%S)%s+(%a%a?%a?)$')  -- mangled "Princess Bride ... The"
  if art=='the' or art=='a' or art=='an' then s=art..' '..front end
  local main=s:gsub('%s*[:;].*$',''):gsub('%s*%b()%s*$','')
  return norm(s),norm(main),tail,s
end
local function surnames(author)
  local out={}
  local s=safe_text(author):lower():gsub('%s+and%s+',','):gsub('&',',')
  for part in s:gmatch('[^,]+') do
    local w=words(part)
    if #w>0 then out[#out+1]=w[#w] end
  end
  return out
end
-- A known, different author vetoes a title match ("The Martian Chronicles" is not Weir's).
local function author_ok(cat_author,reader_author)
  local rw=words(reader_author)
  local set,generic={},true
  for _,w in ipairs(rw) do
    set[w]=true
    if w~='unknown' and w~='author' and w~='none' then generic=false end
  end
  if generic then return true end
  local rn=norm(reader_author)
  for _,sn in ipairs(surnames(cat_author)) do
    if set[sn] or rn:find(sn,1,true) then return true end
  end
  return false
end
local function word_prefix(a,b)
  if #b>#a then return false end
  for i=1,#b do if a[i]~=b[i] then return false end end
  return true
end
local function book_forms(b)
  if not b.forms then
    local key,keymain,_,ct=title_forms(b.title)
    local alias=norm(b.alias or '')
    local w=words(ct)
    b.forms={key=key,keymain=keymain,words=w,alias=alias,two=w[2] and (w[1]..' '..w[2]) or ''}
  end
  return b.forms
end
local forms_memo,author_memo={},{}
local function record_forms(title,author)
  local mk=safe_text(title)..'\0'..safe_text(author)
  if forms_memo[mk] then return forms_memo[mk] end
  local full,main,tail,rt=title_forms(title)
  local ra=safe_text(author)
  if ra=='' then ra=tail end
  local w=words(rt)
  forms_memo[mk]={full=full,main=main,author=ra,words=w,author_key=norm(author),raw=norm(title),
    two=w[2] and (w[1]..' '..w[2]) or ''}
  return forms_memo[mk]
end
-- 'exact' | 'similar' | nil
local function classify_forms(b,f)
  local bf=book_forms(b)
  local key,keymain=bf.key,bf.keymain
  -- The listed file's own metadata title (often junk like "Microsoft Word - ...") is exact.
  if bf.alias~='' and f.raw==bf.alias then return 'exact' end
  -- Title and author swapped in the metadata ("Thompson, Hunter S" by "The Rum Diary").
  if f.author_key~='' and (f.author_key==key or f.author_key==keymain) then return 'exact' end
  local ak=b.author..'\0'..f.author
  if author_memo[ak]==nil then author_memo[ak]=author_ok(b.author,f.author) end
  if not author_memo[ak] then return nil end
  local full,main=f.full,f.main
  if full==key or full==keymain or (main~='' and (main==key or main==keymain)) then return 'exact' end
  local a,w=bf.words,f.words
  if #key>=8 and #full>=8 and math.min(#a,#w)>=2 and (word_prefix(a,w) or word_prefix(w,a)) then
    return 'similar'
  end
  return nil
end
local function classify(b,reader_title,reader_author)
  return classify_forms(b,record_forms(reader_title,reader_author))
end
for _,b in ipairs(books) do b.key=norm(b.title); by_key[b.key]=b end
local ISSUE_ORDER={['LINK CHANGED']=1,MULTIPLE=2,['CHECK TITLE']=3,['NOT OPENED YET']=4,['NOT INDEXED']=5,['NOT ON CARD']=6}
-- Search ONLY the stock reader's opened-book catalogue. It is not an SD scan.
local function refresh_library()
  library,linked={},{}
  scan={ok=false,found=0,issues={},indexed=0,by_book={},cands={}}
  local collected={}
  if ctx and ctx.reader then
    for _,method in ipairs({'all_books','books'}) do
      local ok,res=pcall(function() return ctx.reader[method](ctx.reader) end)
      if ok and type(res)=='table' then
        scan.ok=true
        for _,r in ipairs(res) do
          if type(r)=='table' and r.id and type(r.title)=='string' then
            local id=tostring(r.id)
            local old=collected[id] or {}
            for k,v in pairs(r) do if v~=nil then old[k]=v end end
            collected[id]=old
          end
        end
      end
    end
  end
  for id,r in pairs(collected) do
    r.id=id
    library[#library+1]=r
    linked[id]=r
  end
  -- Same title: most recently read first (a moved file leaves an older twin), then by ID.
  table.sort(library,function(a,b)
    local ta,tb=tostring(a.title):lower(),tostring(b.title):lower()
    if ta~=tb then return ta<tb end
    local da,db=tostring(a.last_date or ''),tostring(b.last_date or '')
    if da~=db then return da>db end
    return tostring(a.id)<tostring(b.id)
  end)
  scan.indexed=#library
  if not scan.ok then
    scan.issues[1]={id=0,title='Reader access unavailable',code='NO ACCESS',
      reason='Check reader permission or update'}
    return
  end
  -- Exact titles (ignoring series tags, subtitles and file-name author tails)
  -- auto-link only when UNIQUE. Similar titles are suggestions, never safe to
  -- launch or silently auto-select.
  -- Only records sharing a title key or the first two words can match; bucket them once.
  local bucket={}
  local function put(k,r)
    if k and k~='' then
      local t=bucket[k]
      if not t then t={};bucket[k]=t end
      if t[#t]~=r then t[#t+1]=r end
    end
  end
  local rank={}
  for i,r in ipairs(library) do
    rank[r]=i
    r.forms=r.forms or record_forms(r.title,r.author)
    put('='..r.forms.full,r); put('='..r.forms.main,r); put('^'..r.forms.two,r)
    put('='..r.forms.author_key,r); put('='..r.forms.raw,r)
  end
  for _,b in ipairs(books) do
    local s=states[b.id]
    local exact,suggest,seen={},{},{}
    local bf=book_forms(b)
    for _,k in ipairs({'='..bf.key,'='..bf.keymain,'='..bf.alias,'^'..bf.two}) do
      for _,r in ipairs(bucket[k] or {}) do
        if not seen[r] then
          seen[r]=true
          local c=classify_forms(b,r.forms)
          if c=='exact' then exact[#exact+1]=r elseif c=='similar' then suggest[#suggest+1]=r end
        end
      end
    end
    -- Keep the reader's order (title, then most recently read) within each group.
    table.sort(exact,function(x,y) return rank[x]<rank[y] end)
    table.sort(suggest,function(x,y) return rank[x]<rank[y] end)
    local cands={}
    for _,r in ipairs(exact) do cands[#cands+1]=r end
    for _,r in ipairs(suggest) do cands[#cands+1]=r end
    scan.cands[b.id]=cands
    -- "Dune" vs "Dune: House Atreides": when only one exact match is the whole title, it wins.
    if #exact>1 then
      local whole={}
      for _,r in ipairs(exact) do
        if r.forms.full==bf.key or r.forms.full==bf.keymain then whole[#whole+1]=r end
      end
      if #whole==1 then exact={whole[1]} end
    end
    local code,reason
    if s.rid~='' then
      if linked[s.rid] then
        scan.found=scan.found+1
      else
        code,reason='LINK CHANGED','Relink: saved ID not found'
      end
    elseif #exact==1 then
      s.rid=exact[1].id
      scan.found=scan.found+1
    elseif #exact>1 then
      code,reason='MULTIPLE','Choose the correct edition'
    elseif #suggest>0 then
      code,reason='CHECK TITLE','Verify similar title before link'
    elseif b.path~='' then
      -- On the card per the directory tree, but the reader has never opened it.
      code,reason='NOT OPENED YET',b.folder
    elseif CARD_DATE~='' then
      code,reason='NOT ON CARD','Copy to Books/, open in Bookshelf'
    else
      code,reason='NOT INDEXED','Open it once in Bookshelf'
    end
    if code then
      scan.by_book[b.id]=code
      scan.issues[#scan.issues+1]={id=b.id,title=b.title,code=code,reason=reason}
    end
  end
  -- Fixable issues first; missing books (often most of the list) last.
  table.sort(scan.issues,function(x,y)
    local px,py=ISSUE_ORDER[x.code] or 9,ISSUE_ORDER[y.code] or 9
    if px~=py then return px<py end
    return x.id<y.id
  end)
end
local function on_card(b)
  return b.path~='' or states[b.id].rid~=''
end
local function percent(b)
  local r=linked[states[b.id].rid]
  if not r then return nil end
  if r.finished then return 100 end
  local p=tonumber(r.percent)
  if p then return math.max(0,math.min(100,math.floor(p+.5))) end
  return nil
end
-- What the reader says counts as "reading" for display, without overwriting the saved choice.
local function shown_status(b)
  local st=states[b.id].status
  if st=='todo' and (percent(b) or 0)>0 then return 'reading' end
  return st
end
local function done_count()
  local n=0
  for _,s in ipairs(states) do if s.status=='done' then n=n+1 end end
  return n
end
-- Up next: a book in progress, else the first unread book that is not an optional reread.
local function current_book()
  for i=1,#books do if states[i].status=='reading' then return books[i] end end
  for i=1,#books do if states[i].status~='done' and not books[i].reread then return books[i] end end
  for i=1,#books do if states[i].status~='done' then return books[i] end end
  return nil
end
local function collect(which)
  if which=='path' then return books end
  local t={}
  for i,b in ipairs(books) do
    if states[i].status=='done' then t[#t+1]=b end
  end
  return t
end
-- The path opens on the page holding the book up next.
local function path_page()
  local b=current_book()
  return b and math.floor((b.id-1)/6)+1 or 1
end
local function font(name)
  return ctx and ctx.fonts and ctx.fonts[name] or nil
end
local function measure(name,s)
  local f=font(name)
  if f then
    local ok,w=pcall(function() return f:measure(s) end)
    if ok and type(w)=='number' then return w end
  end
  return #s * (name=='small' and 10 or 13)
end
local function shorten(name,s,maxwidth)
  s=tostring(s or '')
  if measure(name,s)<=maxwidth then return s end
  local function drop(z) return (z:gsub('[%z\1-\127\192-\255][\128-\191]*$','')) end
  while #s>0 and measure(name,s..'...')>maxwidth do s=drop(s) end
  return s..'...'
end
local function text(g,x,y,s,name,maxwidth)
  s=shorten(name or 'medium',s,maxwidth or W-2*x)
  g:text(x,y,s,{font=font(name or 'medium')})
end
local function line(g,y)
  g:line(12,y,W-12,y,{line_width=1})
end
local function hit(x,y,w,h,fn)
  hits[#hits+1]={x=x,y=y,w=w,h=h,fn=fn}
end
-- Shared-family button treatment: 9px corners, 3px ink, subtle lower edge.
local function button(g,x,y,w,h,label,fn,selected)
  g:rect(x,y,w,h,{line_width=3,radius=9})
  g:rect(x+9,y+h-1,w-18,1,{fill=true,radius=0})
  if selected then g:rect(x+5,y+5,w-10,h-10,{line_width=1,radius=5}) end
  local f='medium'
  local s=shorten(f,label,w-20)
  local tw=measure(f,s)
  text(g,x+math.max(10,math.floor((w-tw)/2)),y+math.floor((h-24)/2),s,f,w-20)
  if fn then hit(x,y,w,h,fn) end
end
local function wrap(s,name,width,maxlines)
  local result,cur,rest={},'',nil
  local ws={}
  for word in tostring(s or ''):gmatch('%S+') do ws[#ws+1]=word end
  for i,word in ipairs(ws) do
    local t=cur=='' and word or (cur..' '..word)
    if cur~='' and measure(name,t)>width then
      result[#result+1]=cur
      cur=word
      if #result>=maxlines-1 then rest=table.concat(ws,' ',i); break end
    else cur=t end
  end
  -- Never drop words silently: the last line holds the remainder, shortened.
  if rest then cur=shorten(name,rest,width) end
  if cur~='' and #result<maxlines then result[#result+1]=cur end
  return result
end
local function set_view(v)
  view,page=v,1
  if v=='path' then page=path_page() end
  refresh_library()
  invalidate()
end
local function detail(b)
  if view~='detail' then detail_origin,detail_page=view,page end
  chosen=b.id
  set_view('detail')
end
local function back_from_detail()
  local target,previous=detail_origin,detail_page
  set_view(target)
  if target=='check' then page=math.min(previous,math.max(1,math.ceil(#scan.issues/6))) end
  invalidate()
end
local function set_status(st,id)
  local s=states[id or chosen]
  s.status=st
  save()
  invalidate()
end
-- Row checkbox: finished <-> not finished (back to Reading if the reader shows progress).
local function toggle_done(b)
  if states[b.id].status=='done' then
    set_status((percent(b) or 0)>0 and 'reading' or 'todo',b.id)
  else
    set_status('done',b.id)
  end
end
local function try_open(b)
  local s=states[b.id]
  if s.rid=='' then
    notify('NOT INDEXED: open the book in Bookshelf once.')
    return
  end
  local target=linked[s.rid]
  if not target then notify('Book not available; open it once in Bookshelf.'); return end
  -- Firmware build 26110501 announced open-book APIs, but older APIs and the exact
  -- call signature differ. Only invoke a supported call on an explicit user tap.
  local function attempts(owner,method,args)
    if not owner or type(owner[method])~='function' then return false end
    for _,a in ipairs(args) do
      local ok,r=pcall(function() return owner[method](owner,a) end)
      if ok and r~=false and r~=nil then return true end
    end
    return false
  end
  local id=s.rid
  local candidates={{type='book',id=id},{kind='book',id=id},'book:'..id}
  if attempts(ctx.reader,'open',candidates) then return end
  if ctx.system and type(ctx.system.can_open)=='function' then
    for _,c in ipairs(candidates) do
      local ok,supported=pcall(function() return ctx.system:can_open(c) end)
      if ok and supported==true and attempts(ctx.system,'open',{c}) then return end
    end
  end
  notify('Open this book from Bookshelf. Direct launch unverified.')
end
-- A book row is a read action. Book management is intentionally secondary.
local function begin_pick(b)
  chosen=b.id
  pick_origin,pick_page=view,page
  view,page='pick',1
  refresh_library()
  -- Likely matches first, then everything else the reader knows.
  pick_list={}
  local seen={}
  for _,r in ipairs(scan.cands[b.id] or {}) do pick_list[#pick_list+1]=r; seen[r.id]=true end
  for _,r in ipairs(library) do if not seen[r.id] then pick_list[#pick_list+1]=r end end
  invalidate()
end
local function leave_pick()
  view,page=pick_origin,pick_page
  refresh_library()
  invalidate()
end
local function open_or_link(b)
  chosen=b.id
  refresh_library()
  local s=states[b.id]
  if s.rid~='' and linked[s.rid] then
    try_open(b)
    return
  end
  local code=scan.by_book[b.id]
  if not scan.ok then
    notify('Reader index unavailable; check permission.')
  elseif code=='MULTIPLE' or code=='CHECK TITLE' or code=='LINK CHANGED' then
    begin_pick(b)  -- candidates are listed first
  elseif code=='NOT OPENED YET' then
    notify('Open once in Bookshelf: Books > '..b.folder)
  elseif code=='NOT ON CARD' then
    notify('Not on the card (book list of '..CARD_DATE..').')
  else
    notify('NOT INDEXED: check Bookshelf, then tap CHECK.')
  end
end
local function draw_head(g,title,subtitle)
  text(g,14,10,title,'large',452)
  text(g,14,47,subtitle,'small',452)
  line(g,75)
end
-- Progress header: what you have read, at a glance.
local function draw_progress_head(g,title)
  local done=done_count()
  local count=done..' / '..#books..' read'
  local cw=measure('medium',count)
  text(g,14,10,title,'large',466-cw-24)
  text(g,466-cw,16,count,'medium',cw+2)
  g:rect(14,52,452,14,{line_width=2,radius=7})
  local fill=math.floor(448*done/#books+.5)
  if fill>0 then g:rect(16,54,math.max(fill,10),10,{fill=true,radius=5}) end
  line(g,75)
end
local function checkbox(g,x,y,st)
  g:rect(x,y,40,40,{line_width=3,radius=9})
  if st=='done' then
    g:line(x+9,y+21,x+17,y+29,{line_width=4})
    g:line(x+17,y+29,x+31,y+12,{line_width=4})
  elseif st=='reading' then
    g:rect(x+12,y+12,16,16,{fill=true,radius=3})
  end
end
local function draw_list(g)
  local ls=view=='check' and scan.issues or collect(view)
  local next_book=current_book()
  if view=='check' then
    draw_head(g,'Book Check',scan.ok and (scan.found..' / '..#books..' identified   |   '..#scan.issues..' issues') or 'Reader index unavailable')
  else
    draw_progress_head(g,'Reading Roadmap')
  end
  local rows=6
  local pages=math.max(1,math.ceil(#ls/rows))
  if page>pages then page=pages end
  local offset=(page-1)*rows
  for slot=1,rows do
    local b=ls[offset+slot]
    if b then
      local y=86+(slot-1)*91
      local st=states[b.id] and shown_status(b) or 'todo'
      local focused=view~='check' and next_book and next_book.id==b.id
      -- Only the book needing attention gets a frame; the remaining rows use quiet dividers.
      if focused then g:rect(9,y,W-18,84,{line_width=3,radius=8})
      else g:line(15,y+83,W-15,y+83,{line_width=1}) end
      if view=='check' then
        text(g,18,y+18,b.id>0 and string.format('%02d',b.id) or '!!','medium',42)
        text(g,67,y+4,b.title,'medium',314)
        text(g,67,y+32,b.code,'small',314)
        text(g,67,y+58,b.reason,'small',314)
      else
        checkbox(g,20,y+22,st)
        local ls_title=wrap(b.title,'medium',318,2)
        local title_y=y+(#ls_title>1 and 4 or 14)
        for i,v in ipairs(ls_title) do text(g,76,title_y+(i-1)*27,v,'medium',318) end
        -- One quiet line: the state when it matters, otherwise the author.
        local p=percent(b)
        local meta=st=='done' and 'Finished'
          or st=='reading' and (p and (p..'% read') or 'Reading')
          or not on_card(b) and 'Not on card'
          or focused and ('Up next  |  '..b.author)
          or b.reread and 'Optional reread'
          or b.author
        text(g,76,y+(#ls_title>1 and 59 or 48),meta,'small',318)
      end
      if view~='check' then g:line(407,y+9,407,y+75,{line_width=1}) end
      text(g,416,y+32,'INFO','small',50)
      if view=='check' then
        hit(9,y,462,84,function()
          if b.id>0 then detail(books[b.id]) else notify('Reader index unavailable.') end
        end)
      else
        hit(9,y,58,84,function() toggle_done(b) end)
        hit(67,y,340,84,function() open_or_link(b) end)
        hit(408,y,63,84,function() detail(b) end)
      end
    end
  end
  if #ls==0 then
    text(g,28,257,view=='check' and 'No indexing issues' or 'No finished books yet','large',428)
    text(g,28,309,view=='check' and 'All titles have reader matches.' or 'Finish a book to see it here.','medium',424)
    button(g,40,422,400,54,'BACK TO PATH',function()set_view('path')end)
  end
  if view=='check' then
    text(g,15,628,CARD_DATE~='' and ('Opened books + card list of '..CARD_DATE) or 'Opened books only; SD not scanned','small',450)
  end
  if page>1 then button(g,12,652,118,54,'< PREV',function() page=page-1;invalidate() end) end
  text(g,183,669,page..' / '..pages,'medium',110)
  if page<pages then button(g,349,652,119,54,'NEXT >',function() page=page+1;invalidate() end) end
  button(g,8,725,148,58,'PATH',function() set_view('path') end,view=='path')
  button(g,166,725,148,58,'DONE',function() set_view('done') end,view=='done')
  button(g,324,725,148,58,'CHECK',function() set_view('check') end,view=='check')
end
local function draw_detail(g)
  local b=by_id[chosen]
  if not b then set_view('path');return end
  local st=states[b.id].status
  draw_head(g,'Book '..b.id..' of '..#books,b.genre..'  |  Stage '..b.stage..(b.reread and '  |  Optional reread' or ''))
  local title_lines=wrap(b.title,'large',444,2)
  for i,v in ipairs(title_lines) do text(g,18,91+(i-1)*35,v,'large',444) end
  local ay=91+#title_lines*35+7
  text(g,18,ay,b.author~='' and b.author or 'Author not in file name','medium',444)
  local rule_y=ay+38
  line(g,rule_y)
  -- Optional sections in priority order; each is shortened or left out so the
  -- card section and the fixed controls below never move or overlap.
  local LIMIT,CARD_H=572,83
  local y=rule_y+18
  for _,sec in ipairs({{'WHY THIS BOOK',b.note,3},{'HEADS-UP',b.warning,2},{'VISUAL REFERENCE',b.anchor,2}}) do
    if sec[2]~='' then
      local n=sec[3]
      while n>0 and y+29+n*30+22+CARD_H>LIMIT do n=n-1 end
      if n>0 then
        text(g,18,y,sec[1],'small',442)
        local ls=wrap(sec[2],'medium',430,n)
        for i,v in ipairs(ls) do text(g,18,y+29+(i-1)*30,v,'medium',438) end
        y=y+29+#ls*30+22
      end
    end
  end
  local p=percent(b)
  text(g,18,y,'ON YOUR XTEINK','small',440)
  text(g,18,y+29,p and ('Reader progress: '..p..'%') or (states[b.id].rid~='' and 'Linked: no progress reported' or 'Not linked to an opened book'),'medium',440)
  local where=b.path~='' and ('Books > '..b.folder..' ('..b.fmt..')') or ('Not in the card list of '..CARD_DATE)
  text(g,18,y+59,where,'small',440)
  -- Status is one explicit choice, and every choice can be undone.
  button(g,15,584,146,55,'TO READ',function() set_status('todo') end,st=='todo')
  button(g,167,584,146,55,'READING',function() set_status('reading') end,st=='reading')
  button(g,319,584,146,55,'FINISHED',function() set_status('done') end,st=='done')
  if states[b.id].rid=='' then
    button(g,15,650,450,55,'LINK BOOK',function() begin_pick(b) end)
  else
    button(g,15,650,218,55,'LINK BOOK',function() begin_pick(b) end)
    button(g,247,650,218,55,'OPEN BOOK',function() try_open(b) end)
  end
  button(g,15,723,450,59,'BACK TO LIST',function() back_from_detail() end)
end
local function draw_pick(g)
  draw_head(g,'LINK A BOOK','Choose a book you have opened in Bookshelf.')
  local pages=math.max(1,math.ceil(#pick_list/6))
  if page>pages then page=pages end
  for slot=1,6 do
    local r=pick_list[(page-1)*6+slot]
    if r then
      local y=87+(slot-1)*90
      g:rect(10,y,460,82,{line_width=1})
      text(g,19,y+8,r.title or 'Untitled','medium',440)
      local sub=safe_text(r.author)
      if sub=='' and r.last_date then sub='Last read '..safe_text(r.last_date) end
      if (page-1)*6+slot<=#(scan.cands[chosen] or {}) then sub='MATCH  |  '..sub end
      text(g,19,y+42,sub,'small',440)
      hit(10,y,460,82,function()
        states[chosen].rid=tostring(r.id)
        save()
        local return_to=pick_origin
        leave_pick()
        if return_to~='detail' then try_open(books[chosen]) end
      end)
    end
  end
  if #pick_list==0 then
    text(g,18,115,'No opened books were reported by the reader.','medium',440)
    text(g,18,154,'Open the book in Bookshelf first.','medium',440)
  end
  if page>1 then button(g,12,652,118,54,'< PREV',function() page=page-1;invalidate() end) end
  text(g,190,669,page..' / '..pages,'medium',92)
  if page<pages then button(g,349,652,119,54,'NEXT >',function() page=page+1;invalidate() end) end
  button(g,15,725,450,56,'BACK',function()leave_pick()end)
end
function on_load(c)
  ctx=c or ctx
  load()
  refresh_library()
  page=path_page()  -- open where the reader left off
end
function on_draw(c,g)
  ctx=c or ctx
  hits={}
  g:clear(0)
  if view=='detail' then draw_detail(g)
  elseif view=='pick' then draw_pick(g)
  else draw_list(g) end
  if msg~='' then
    text(g,15,(view=='detail' or view=='pick') and 782 or 628,msg,'small',450)
    msg=''
  end
end
function on_input(c,e)
  ctx=c or ctx
  if not e then return end
  if e.type=='key' then
    local ph=e.phase or e.action or e.state
    if ph=='up' or ph=='release' or e.pressed==false then return end
    local ms=tonumber(e.time_ms)
    if last_key==e.key and ms and last_ms and ms-last_ms>=0 and ms-last_ms<230 then return end
    last_key,last_ms=e.key,ms
    if e.key=='back' then
      if view=='pick' then leave_pick() elseif view=='detail' then back_from_detail() end
    elseif e.key=='right' or e.key=='down' then page=page+1;invalidate()
    elseif e.key=='left' or e.key=='up' then page=math.max(1,page-1);invalidate()
    elseif e.key=='ok' and view=='path' then open_or_link(current_book() or books[1])
    end
    return
  end
  if (e.type=='pointer' and e.phase=='up') or (e.type=='touch' and (e.gesture=='tap' or e.phase=='up')) then
    local x,y=tonumber(e.x),tonumber(e.y)
    if not x or not y then return end
    for i=#hits,1,-1 do
      local h=hits[i]
      if x>=h.x and x<h.x+h.w and y>=h.y and y<h.y+h.h then h.fn();invalidate();return end
    end
  end
end
function on_leave() end
